        public static UnitConverterVolumeUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterVolumeUnit>();
            for (int i = 0; i < 95; i++) if (GetUnitSystem((UnitConverterVolumeUnit)i) == system) units.Add((UnitConverterVolumeUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterVolumeUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterVolumeUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterVolumeUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterVolumeUnit)id : default(UnitConverterVolumeUnit); return success;
        }

        public static UnitConverterVolumeUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterVolumeUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Volume unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterVolumeValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterVolumeValue(value, (UnitConverterVolumeUnit)id) : default(UnitConverterVolumeValue); return success;
        }

        public static UnitConverterVolumeValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterVolumeValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Volume unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterVolumeUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
